    /// to establish connection upfront.
    /// </summary>
    abstract connect: unit -> JS.Promise<unit>
    /// <summary>
    /// Disconnect WebSocket transport (no-op in HTTP mode)
    /// Should be called when the sandbox is destroyed.
    /// </summary>
    abstract disconnect: unit -> unit
